def build_lane_query(base_query: str, lane: str, seed_context: NonfeedSeedContext | None=None) -> str | dict:
    """
    Shape a source-specific query for an acquisition lane.

    F222I: When seed_context is provided (pivot/DuckDB domain extraction),
    lanes receive the extracted domain/IP seed instead of the generic text query.
    This enables CT/DOH/PassiveDNS/Wayback for "LockBit ransomware" style queries
    that have no explicit domain/IP in the raw query text.

    Rules per lane:
      CT:          seed.domains[0] if available, else extract domains from base_query
      WAYBACK:     seed.domains[0] or seed.urls[0] if available, else base_query
      PASSIVE_DNS: seed.domains[0] or seed.ips[0] if available, else base_query
      BLOCKCHAIN:  wallet/hash only; returns {"_disabled": True} if no crypto indicator
      PUBLIC:      original query plus 1-2 bounded variants (seed ignored)
      FEED:        original query unchanged (seed ignored)

    No LLM, no network I/O. Deterministic.

    Args:
        base_query:  The sprint query string.
        lane:        One of AcquisitionLane values.
        seed_context: Optional NonfeedSeedContext from pivot/DuckDB extraction.

    Returns:
        Shaped query string, or a dict with lane guidance (e.g. {"_disabled": True}).
        Returns {"_disabled": True} for BLOCKCHAIN when no crypto indicator present.
    """
    if lane == AcquisitionLane.CT:
        if seed_context and seed_context.domains:
            return seed_context.domains[0]
        domains = _DOMAIN_OR_IP_RE.findall(base_query)
        if domains:
            unique = list(dict.fromkeys(domains))[:5]
            return ' '.join(unique)
        return ''
    elif lane == AcquisitionLane.WAYBACK:
        if seed_context and seed_context.domains:
            return seed_context.domains[0]
        if seed_context and seed_context.urls:
            return seed_context.urls[0]
        domains = _DOMAIN_OR_IP_RE.findall(base_query)
        if domains:
            return domains[0]
        return ''
    elif lane == AcquisitionLane.PASSIVE_DNS:
        return normalize_passive_dns_query(base_query, seed_context)
    elif lane == AcquisitionLane.BLOCKCHAIN:
        wallets = _extract_crypto_from_query(base_query)
        if wallets:
            return wallets[0]
        return {'_disabled': True, 'reason': 'no_crypto_indicator'}
    elif lane == AcquisitionLane.DOH:
        if seed_context and seed_context.domains:
            return seed_context.domains[0]
        ips = _extract_ips_from_query(base_query)
        domains = [d for d in _DOMAIN_OR_IP_RE.findall(base_query) if not _looks_like_ip(d)]
        if domains:
            return domains[0]
        if ips:
            return {'_disabled': True, 'reason': 'ip_seed_reverse_doh_deferred'}
        return {'_disabled': True, 'reason': 'no_domain_seed'}
    elif lane == AcquisitionLane.PUBLIC:
        try:
            from hledac.universal.runtime.osint_query_expander import expand_osint_query
            variants = expand_osint_query(base_query, max_variants=1)
            if variants:
                return variants[0][:200]
        except Exception:
            pass
        trimmed = base_query[:200] if len(base_query) > 200 else base_query
        return trimmed
    return base_query

def _looks_like_domain(value: str) -> bool:
    """Return True if value looks like a domain name (no IP, has TLD)."""
    if not value or len(value) > 253:
        return False
    if '.' not in value:
        return False
    if re.match('^\\d{1,3}(?:\\.\\d{1,3}){3}$', value):
        return False
    parts = value.split('.')
    if len(parts) < 2:
        return False
    tld = parts[-1]
    if len(tld) < 1 or len(tld) > 63:
        return False
    if not re.match('^[a-z0-9.\\-_]+$', tld):
        return False
    return True

def _extract_domain_from_ct_finding(finding: Any) -> str | None:
    """
    Extract domain from a CT CanonicalFinding (or dict-like) object.

    Strategy:
        1. Try payload_text: parse "domain: <value>" lines
        2. Fallback: query field

    Returns:
        Normalized lowercase domain string, or None if not extractable.
    """
    payload: str | None = getattr(finding, 'payload_text', None)
    if payload and isinstance(payload, str):
        for line in payload.splitlines():
            line = line.strip()
            if line.startswith('domain:'):
                domain = line[len('domain:'):].strip()
                if domain:
                    return domain.lower()
        for line in payload.splitlines():
            line = line.strip()
            if line and (not line.startswith('#')) and ('.' in line):
                if len(line) <= 253 and ' ' not in line and (line.startswith(('www.', 'http', '//')) is False):
                    if re.match('^[a-z0-9.\\-_]+$', line):
                        return line.lower()
    query: str = getattr(finding, 'query', '') or ''
    if query:
        domains = _DOMAIN_OR_IP_RE.findall(query)
        if domains:
            for d in domains:
                if d and '.' in d and (not _looks_like_ip(d)):
                    return d.lower()
        if _looks_like_domain(query.strip()):
            return query.strip().lower()
    return None

def effective_windup_lead_s(self) -> float:
    """Adaptive windup that scales with sprint duration.

    F290: Short sprints get smaller windup overhead.
    F285: Explicit windup_lead_s (non-default 180.0) passes through directly.
    F273B + F288: Aggressive mode → 15% ratio.
    """
    if self.windup_lead_s is not None and self.windup_lead_s != 180.0:
        return float(max(30.0, min(180.0, float(self.windup_lead_s))))
    if self.aggressive_mode:
        ratio = 0.15
    elif self.sprint_duration_s <= 120.0:
        ratio = 0.2
    elif self.sprint_duration_s <= 300.0:
        ratio = 0.25
    else:
        ratio = 0.3
    raw = self.sprint_duration_s * ratio
    return float(max(15.0, min(180.0, raw)))

def final_windup_lead_s(self) -> float:
    """Adaptive windup for sprint-end synthesis and graceful shutdown.

    Matches effective_windup_lead_s ratio tiers but with [30, 180] floor.
    """
    if self.windup_lead_s != 180.0:
        result = float(min(45.0, self.windup_lead_s))
        logger.info('[WINDUP] final_windup=%.1fs (explicit)', result)
        return result
    if self.aggressive_mode:
        ratio = 0.15
    elif self.sprint_duration_s <= 120.0:
        ratio = 0.2
    elif self.sprint_duration_s <= 300.0:
        ratio = 0.25
    else:
        ratio = 0.3
    raw = self.sprint_duration_s * ratio
    result = float(max(30.0, min(180.0, raw)))
    logger.info('[WINDUP] lead=%.1fs', result)
    return result

def _prefetch_pipeline_factory(*, duckdb_store: Any) -> Any:
    from hledac.universal.layers import get_temporal_signal_layer
    from hledac.universal.prefetch.prefetch_pipeline import (
        ContinuousPrefetchPipeline,
    )
    from hledac.universal.prefetch.temporal_predictor import (
        TemporalIOCPredictor,
    )

    temporal_predictor = TemporalIOCPredictor(
        temporal_layer=get_temporal_signal_layer(),
        duckdb_store=duckdb_store,
    )
    prefetch_pipeline = ContinuousPrefetchPipeline(
        prefetch_oracle=temporal_predictor,
        prefetch_cache=None,
        queue_depth=50,
        concurrent_fetches=3,
    )
    return (prefetch_pipeline, temporal_predictor)

async def _apply_injections(
    self,
    *,
    query: str,
    flags: Any,
    sprint_id: str,
    sprint_duration_s: float,
    windup_lead_s: float,
    duckdb_store: Any,
    rl_train_mode: bool,
    logger: _logging.Logger,
) -> None:
    """Apply all declarative injections to scheduler."""
    if flags is None:
        flags = _FlagsEmpty()

    sorted_injections = sorted(INJECTIONS, key=lambda i: i.order)

    for inj in sorted_injections:
        if inj.gate_attr is not None and getattr(flags, inj.gate_attr, False):
            logger.debug("V2Init: %s skipped (gate: %s)", inj.name, inj.gate_attr)
            continue

        factory_kwargs: dict[str, Any] = {}
        if inj.name == "evidence_log":
            factory_kwargs["sprint_id"] = sprint_id
        elif inj.name == "policy_manager":
            factory_kwargs["rl_train_mode"] = rl_train_mode
        elif inj.name in ("duckdb_store", "prefetch_pipeline"):
            factory_kwargs["duckdb_store"] = duckdb_store

        try:
            obj = inj.factory(**factory_kwargs)

            if inj.name == "evidence_log" and obj is not None:
                _evidence_log_init(obj, sprint_id, query, sprint_duration_s, windup_lead_s)

            if inj.name == "prefetch_pipeline" and obj is not None:
                prefetch_pipeline, temporal_predictor = obj
                inj_method = getattr(self._scheduler, f"inject_{inj.name}", None)
                if inj_method:
                    inj_method(prefetch_pipeline)
                tp_inject = getattr(self._scheduler, "inject_temporal_predictor", None)
                if tp_inject and temporal_predictor is not None:
                    tp_inject(temporal_predictor)
            else:
                inj_method = getattr(self._scheduler, f"inject_{inj.name}", None)
                if inj_method and obj is not None:
                    inj_method(obj)

        except Exception as e:
            if inj.fail_soft:
                logger.debug("V2Init: %s injection failed (fail-soft): %s", inj.name, e)
