def gauge(self, label: str, val: float, **extra: Any) -> None:
    """
    Record a point-in-time metric (gauge).

    Fail-soft: any exception is swallowed.
    """
    event: dict[str, Any] = {
        "label": label,
        "elapsed_s": 0.0,
        "metadata": {"val": val, "type": "gauge", **(extra or {})},
    }
    self._events.append(event)
    if self._emit_fn is not None:
        try:
            self._emit_fn(label, 0.0, {"val": val, "type": "gauge", **(extra or {})})
        except Exception:  # noqa: BLE001
            pass  # noqa: BLE001  # fail-soft: never propagate

def record(self, label: str, elapsed_s: float = 0.0, **metadata: Any) -> None:
    """
    Record a completed timer event with explicit elapsed time.

    Fail-soft: any exception is swallowed.
    """
    event: dict[str, Any] = {
        "label": label,
        "elapsed_s": elapsed_s,
        "metadata": dict(metadata),
    }
    self._events.append(event)
    if self._emit_fn is not None:
        try:
            self._emit_fn(label, elapsed_s, metadata)
        except Exception:  # noqa: BLE001
            pass  # noqa: BLE001  # fail-soft: never propagate

def decode(bundle_bytes: bytes) -> dict[str, Any]:
    """
    Parse STIX bundle bytes back to a Python dict.

    Tries Rust stix_2_1.decode_bundle() first.
    Falls back to json.loads on error.

    Args:
        bundle_bytes: STIX bundle as bytes

    Returns:
        Parsed STIX bundle dict
    """
    rust = _get_rust_stix()
    if rust is not None:
        try:
            result = rust.decode_bundle(bundle_bytes)
            if isinstance(result, str):
                parsed = _json_loads(result)
                if "error" not in parsed:
                    return parsed
        except Exception as exc:  # noqa: BLE001
            logger.warning(f"[stix] Rust decode_bundle failed: {exc}, falling back to Python")

    try:
        return _json_loads(bundle_bytes)
    except Exception:
        return {"error": "failed to decode STIX bundle"}

